import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <float.h>
#include <stdint.h>

__global__ void min_dim1_kernel(const float* __restrict__ x,
                                float* __restrict__ out,
                                int B, int M, int N) {
    // One thread owns one output column and reduces the full M extent in
    // registers, so no shared-memory reduction or __syncthreads is needed.
    // A block covers blockDim.x consecutive columns, so every row visit
    // reads a wide contiguous segment (blockDim.x * 4 bytes) instead of a
    // narrow 256-byte strip. This keeps DRAM pages open across the 16 KB
    // row-to-row jumps and improves sustained memory throughput for this
    // strided column-wise reduction. Loads stay fully coalesced:
    // consecutive threadIdx.x still touch consecutive addresses.
    const int b = blockIdx.y;
    const int j = blockIdx.x * blockDim.x + threadIdx.x;
    if (b >= B || j >= N) return;
    const size_t stride = (size_t)N;
    const float* p = x + (size_t)b * (size_t)M * stride + (size_t)j;
    float mn = FLT_MAX;
    int i = 0;
    // Unroll 8 rows per iteration to keep enough independent loads in
    // flight to hide global-memory latency.
    for (; i + 7 < M; i += 8) {
        const float v0 = __ldg(p + (size_t)(i + 0) * stride);
        const float v1 = __ldg(p + (size_t)(i + 1) * stride);
        const float v2 = __ldg(p + (size_t)(i + 2) * stride);
        const float v3 = __ldg(p + (size_t)(i + 3) * stride);
        const float v4 = __ldg(p + (size_t)(i + 4) * stride);
        const float v5 = __ldg(p + (size_t)(i + 5) * stride);
        const float v6 = __ldg(p + (size_t)(i + 6) * stride);
        const float v7 = __ldg(p + (size_t)(i + 7) * stride);
        mn = fminf(mn, fminf(fminf(fminf(v0, v1), fminf(v2, v3)),
                             fminf(fminf(v4, v5), fminf(v6, v7))));
    }
    for (; i < M; ++i) {
        mn = fminf(mn, __ldg(p + (size_t)i * stride));
    }
    out[(size_t)b * stride + (size_t)j] = mn;
}

torch::Tensor min_dim1_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 3, "x must be 3D");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    const int B = (int)x.size(0);
    const int M = (int)x.size(1);
    const int N = (int)x.size(2);

    auto out = torch::empty({B, N}, x.options());

    const dim3 block(512);
    const dim3 grid((N + (int)block.x - 1) / (int)block.x, B);
    auto stream = at::cuda::getCurrentCUDAStream();

    min_dim1_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, M, N
    );
    return out;
}
"""

_cpp_src = "torch::Tensor min_dim1_cuda(torch::Tensor x);"

_min_mod = load_inline(
    name="min_dim1_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["min_dim1_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        d = self.dim if self.dim >= 0 else x.dim() + self.dim
        if x.dim() == 3 and d == 1 and x.dtype == torch.float32:
            x = x.contiguous()
            if not x.is_cuda:
                x = x.cuda()
            return _min_mod.min_dim1_cuda(x)
        return torch.min(x, dim=self.dim)[0]

